func repeatable(_ kind: String) -> Bool {
    ["rvr", "weather", "cloud"].contains(kind)
}

typealias WordGroup = (Int, String)

final class Trend {
    let kind: String, times: [String], groups: [WordGroup]
    let section = Section([], true)
    init(_ kind: String, _ times: [String], _ groups: [WordGroup]) {
        self.kind = kind
        self.times = times
        self.groups = groups
    }
}

func splitMetar(_ groups: [WordGroup]) -> ([WordGroup], [[WordGroup]], [WordGroup]) {
    let r = groups.firstIndex {
        $0.1 == "RMK"
    } ?? groups.count
    let before = Array(groups.prefix(r)), remarks = Array(groups.dropFirst(r + 1))
    let t = before.firstIndex {
        ["BECMG", "TEMPO"].contains($0.1)
    } ?? before.count
    var trends: [[WordGroup]] = []
    for g in before.dropFirst(t) {
        if ["BECMG", "TEMPO"].contains(g.1) {
            trends.append([])
        }
        trends[trends.count - 1].append(g)
    }
    return (Array(before.prefix(t)), trends, remarks)
}

func readTrend(_ groups: [WordGroup], _ errors: inout [WordGroup]) -> Trend? {
    func time(_ i: Int, _ prefixes: [String]) -> Bool {
        i < groups.count && captures("(FM|TL|AT)([0-9]{4})", groups[i].1) != nil && prefixes.contains(slice(groups[i].1, 0, 2))
    }
    let count = time(1, ["FM"]) ? (time(2, ["TL"]) ? 2 : 1) : (time(1, ["TL", "AT"]) ? 1 : 0)
    var times: [String] = []
    for (position, text) in groups.dropFirst().prefix(count) {
        if Int(slice(text, 2, 4))! > 23 || Int(slice(text, 4))! > 59 {
            errors.append((position, "invalid period \"\(text)\""))
            return nil
        }
        times.append(text)
    }
    return Trend(groups[0].1, times, Array(groups.dropFirst(1 + count)))
}

func readRemarks(_ groups: [WordGroup]) -> ([Int], [(Int, Int)]) {
    var pressures: [Int] = [], temperatures: [(Int, Int)] = []
    for (_, text) in groups {
        if let m = captures("SLP([0-9]{3})", text) {
            let p = Int(m[0])!
            pressures.append((p >= 500 ? 9000 : 10000) + p)
        }
        if let m = captures("T([01])([0-9]{3})([01])([0-9]{3})", text) {
            temperatures.append((Int(m[1])! * (m[0] == "1" ? -1 : 1), Int(m[3])! * (m[2] == "1" ? -1 : 1)))
        }
    }
    return (pressures, temperatures)
}

import Foundation

let tafSlots = ["wind", "visibility", "weather", "cloud"]

let temporaryKinds = ["TEMPO", "PROB30", "PROB40", "PROB30 TEMPO", "PROB40 TEMPO"]

final class Change {
    let kind: String, start: Int, end: Int, groups: [WordGroup]
    var state = State()
    init(_ kind: String, _ start: Int, _ end: Int, _ groups: [WordGroup]) {
        self.kind = kind
        self.start = start
        self.end = end
        self.groups = groups
    }
}

final class Forecast {
    let number: Int, station: Station, issue: Int, modifier: String, start: Int, end: Int
    var base = State(), changes: [Change] = []
    init(_ number: Int, _ station: Station, _ issue: Int, _ modifier: String, _ start: Int, _ end: Int) {
        self.number = number
        self.station = station
        self.issue = issue
        self.modifier = modifier
        self.start = start
        self.end = end
    }
}

func fmIndicator(_ t: String) -> Bool {
    captures("FM([0-9]{6})", t) != nil
}

func changeIndicator(_ t: String) -> Bool {
    ["BECMG", "TEMPO", "PROB30", "PROB40"].contains(t) || fmIndicator(t)
}

func parsePeriod(_ t: String, _ issueDay: Int, _ c: Calendar) -> (Int, Int)? {
    guard let m = captures("([0-9]{2})([0-9]{2})/([0-9]{2})([0-9]{2})", t) else {
        return nil
    }
    let n = m.map {
        Int($0)!
    }
    if n[1] > 23 || n[3] < 1 || n[3] > 24 {
        return nil
    }
    guard let s = c.forecastTime(n[0], n[1], 0, issueDay), let e = c.forecastTime(n[2], n[3], 0, issueDay), s < e else {
        return nil
    }
    return (s, e)
}

func splitChanges(_ f: Forecast, _ groups: [WordGroup], _ c: Calendar, _ errors: inout [WordGroup]) -> ([WordGroup], [Change]) {
    var i = 0
    while i < groups.count && !changeIndicator(groups[i].1) {
        i += 1
    }
    let base = Array(groups.prefix(i))
    var changes: [Change] = []
    while i < groups.count { let indicator = groups[i]
        i += 1
        var kind = indicator.1, start: Int? = nil, end = 0
        if ["PROB30", "PROB40"].contains(kind) && i < groups.count && groups[i].1 == "TEMPO" {
            kind += " TEMPO"
            i += 1
        }
        if fmIndicator(kind) {
            let d = Int(slice(kind, 2, 4))!, h = Int(slice(kind, 4, 6))!, m = Int(slice(kind, 6))!
            start = h <= 23 && m <= 59 ? c.forecastTime(d, h, m, f.issue / 1440 + 1) : nil
            if let t = start, t >= f.start && t < f.end {
                kind = "FM"
                end = t
            } else {
                errors.append((indicator.0, "invalid period \"\(kind)\""))
                start = nil
            }
        } else if i == groups.count || captures("([0-9]{4})/([0-9]{4})", groups[i].1) == nil {
            errors.append((indicator.0, "missing period \"\(kind)\""))
        } else {
            let p = groups[i]
            i += 1
            if let period = parsePeriod(p.1, f.issue / 1440 + 1, c), period.0 >= f.start && period.1 <= f.end {
                start = period.0
                end = period.1
            } else {
                errors.append((p.0, "invalid period \"\(p.1)\""))
            }
        }
        let first = i
        while i < groups.count && !changeIndicator(groups[i].1) {
            i += 1
        }
        if let start {
            changes.append(Change(kind, start, end, Array(groups[first..<i])))
        }
    }
    return (base, changes)
}

func overlay(_ s: State, _ c: State) -> State {
    State(c.wind ?? s.wind, c.visibility ?? s.visibility, c.weather ?? s.weather, c.cloud ?? s.cloud)
}

func prevailing(_ f: Forecast, _ h: Int) -> State {
    var state = f.base
    for c in f.changes {
        if c.kind == "FM" && c.start <= h {
            state = c.state
        } else if c.kind == "BECMG" && c.end <= h {
            state = overlay(state, c.state)
        }
    }
    return state
}

func temporary(_ f: Forecast, _ h: Int) -> [(String, State)] {
    let p = prevailing(f, h)
    return f.changes.filter {
        temporaryKinds.contains($0.kind) && $0.start <= h && h < $0.end
    }.map {
        ($0.kind, overlay(p, $0.state))
    }
}

import Foundation

func floorDiv(_ n: Int, _ d: Int) -> Int {
    n >= 0 ? n / d : -((-n + d - 1) / d)
}

func knots(_ v: Int, _ unit: String) -> Int {
    unit == "MPS" ? (v * 1944 + 500) / 1000 : v
}

func inhg(_ q: Int) -> Int {
    (q * 2953 + 500) / 1000
}

func hpa(_ a: Int) -> Int {
    (a * 33864 + 50000) / 100000
}

let sineTable = [0, 174, 342, 500, 643, 766, 866, 940, 985, 1000]

func sine(_ x: Int) -> Int {
    let y = (x % 360 + 360) % 360
    if y <= 90 {
        return sineTable[y / 10]
    }
    if y <= 180 {
        return sineTable[(180 - y) / 10]
    }
    if y <= 270 {
        return -sineTable[(y - 180) / 10]
    }
    return -sineTable[(360 - y) / 10]
}

func cosine(_ x: Int) -> Int {
    sine(x + 90)
}

func daysInMonth(_ y: Int, _ m: Int) -> Int {
    if m == 2 {
        return y % 4 == 0 && (y % 100 != 0 || y % 400 == 0) ? 29 : 28
    }
    return [1, 3, 5, 7, 8, 10, 12].contains(m) ? 31 : 30
}

func dayMinutes(_ d: Int, _ h: Int, _ m: Int) -> Int {
    ((d - 1) * 24 + h) * 60 + m
}

func pad(_ n: Int, _ width: Int) -> String {
    let s = String(n)
    return String(repeating: "0", count: max(0, width - s.count)) + s
}

struct Calendar {
    let year: Int, month: Int
    var days: Int {
        daysInMonth(year, month)
    }
    var nextYear: Int {
        month == 12 ? year + 1 : year
    }
    var nextMonth: Int {
        month == 12 ? 1 : month + 1
    }
    func forecastTime(_ d: Int, _ h: Int, _ m: Int, _ issueDay: Int) -> Int? {
        let next = d < issueDay
        if d < 1 || d > daysInMonth(next ? nextYear : year, next ? nextMonth : month) {
            return nil
        }
        return (next ? days * 1440 : 0) + dayMinutes(d, h, m)
    }
    func stamp(_ time: Int) -> String {
        let next = time >= days * 1440, t = time - (time >= days * 1440 ? days * 1440 : 0)
        return "\(pad(next ? nextYear : year, 4))-\(pad(next ? nextMonth : month, 2))-\(pad(t / 1440 + 1, 2))T\(pad(t % 1440 / 60, 2)):\(pad(t % 60, 2))Z"
    }
}

func miles(_ g: Group) -> (Int, Int) {
    if g.visibilityKind == "MILES" {
        return g.denominator == 0 ? (g.whole, 1) : (g.whole * g.denominator + g.numerator, g.denominator)
    }
    return (1000 * g.meters, 1609344)
}

func meterValue(_ g: Group) -> Int {
    let (n, d) = miles(g)
    return g.visibilityKind == "MILES" ? 1609344 * n / (1000 * d) : g.meters
}

func lessFraction(_ a: (Int, Int), _ b: (Int, Int)) -> Bool {
    a.0 * b.1 < b.0 * a.1
}

func fraction(_ n: Int, _ d: Int) -> String {
    if d == 0 {
        return "undefined"
    }
    var a = abs(n), b = abs(d)
    while b != 0 {
        let r = a % b
        a = b
        b = r
    }
    let sign = d < 0 ? -1 : 1
    return "\(n / a * sign)/\(d / a * sign)"
}

import Foundation

let categories = ["VFR", "MVFR", "IFR", "LIFR"]

func covers(_ f: Forecast, _ t: Int) -> Bool {
    f.issue <= t && f.start <= t - t % 60 && t - t % 60 < f.end
}

func chosenForecast(_ fs: [Forecast], _ t: Int) -> Forecast? {
    var chosen: Forecast? = nil
    for f in fs {
        if covers(f, t) && (chosen == nil || f.issue >= chosen!.issue) {
            chosen = f
        }
    }
    return chosen
}

final class Contingency {
    var table = Array(repeating: Array(repeating: 0, count: 4), count: 4)
    var temporaryHits = 0
    func add(_ expected: String, _ observed: String, _ hit: Bool) {
        table[categories.firstIndex(of: expected)!][categories.firstIndex(of: observed)!] += 1
        if hit {
            temporaryHits += 1
        }
    }
    func row(_ i: Int) -> Int {
        table[i].reduce(0, +)
    }
    func column(_ i: Int) -> Int {
        table.reduce(0) {
            $0 + $1[i]
        }
    }
    var total: Int {
        table.reduce(0) {
            $0 + $1.reduce(0, +)
        }
    }
    var hits: Int {
        (0..<4).reduce(0) {
            $0 + table[$1][$1]
        }
    }
    var skill: (Int, Int) {
        let e = (0..<4).reduce(0) {
            $0 + row($1) * column($1)
        }
        return (total * hits - e, total * total - e)
    }
    func detection(_ i: Int) -> (Int, Int) {
        (table[i][i], column(i))
    }
    func falseAlarm(_ i: Int) -> (Int, Int) {
        (row(i) - table[i][i], row(i))
    }
}
